func load16[T uint32 | uint64](mem []byte, addr T) uint16 {
	if !unalignedOK {
		return binary.LittleEndian.Uint16(mem[addr:])
	}
	_ = mem[uint64(addr)+1]
	val := *(*uint16)(unsafe.Add(unsafe.Pointer(unsafe.SliceData(mem)), uintptr(addr)))
	if big {
		return bits.ReverseBytes16(val)
	}
	return val
}

//go:nosplit
